package com.gielinorgoals.model;

import javax.annotation.Nullable;
import lombok.EqualsAndHashCode;
import lombok.Getter;

/**
 * Nå en viss combat level, räknad med {@code Experience.getCombatLevel} och riktiga
 * (inte boostade) nivåer ur XP i spelläget.
 */
@Getter
@EqualsAndHashCode(callSuper = false)
public class CombatLevelRequirement extends Requirement
{
	public static final int MIN = AccountLevels.MIN_COMBAT_LEVEL;
	public static final int MAX = AccountLevels.MAX_COMBAT_LEVEL;

	private int target;

	// För Gson.
	CombatLevelRequirement()
	{
	}

	public CombatLevelRequirement(int target)
	{
		if (target < MIN || target > MAX)
		{
			throw new IllegalArgumentException("Combat level must be between " + MIN + " and " + MAX);
		}
		this.target = target;
	}

	@Override
	public RequirementType getType()
	{
		return RequirementType.COMBAT_LEVEL;
	}

	@Override
	public String describe()
	{
		return "Combat level " + target;
	}

	@Override
	public boolean isValid()
	{
		return target >= MIN && target <= MAX;
	}

	@Nullable
	@Override
	public GoalProgress progress(GameData data)
	{
		// Okänd data ger okänd progress, så att målet aldrig bockas av på saknad data.
		int current = AccountLevels.combatLevel(data);
		return current < 0 ? null : AccountLevels.progress(current, target);
	}

	@Override
	public String describeProgress(GoalProgress progress)
	{
		return AccountLevels.describe("Combat level ", progress, "level", "levels");
	}
}

