package com.gielinorgoals.model;

import javax.annotation.Nullable;
import lombok.EqualsAndHashCode;
import lombok.Getter;

/**
 * Nå en viss total level, räknad med riktiga nivåer (max 99 per skill) ur XP i spelläget.
 */
@Getter
@EqualsAndHashCode(callSuper = false)
public class TotalLevelRequirement extends Requirement
{
	public static final int MIN = AccountLevels.MIN_TOTAL_LEVEL;
	public static final int MAX = AccountLevels.MAX_TOTAL_LEVEL;

	private int target;

	// För Gson.
	TotalLevelRequirement()
	{
	}

	public TotalLevelRequirement(int target)
	{
		if (target < MIN || target > MAX)
		{
			throw new IllegalArgumentException("Total level must be between " + MIN + " and " + MAX);
		}
		this.target = target;
	}

	@Override
	public RequirementType getType()
	{
		return RequirementType.TOTAL_LEVEL;
	}

	@Override
	public String describe()
	{
		return "Total level " + target;
	}

	@Override
	public boolean isValid()
	{
		return target >= MIN && target <= MAX;
	}

	@Nullable
	@Override
	public GoalProgress progress(GameData data)
	{
		// Okänd data ger okänd progress, så att målet aldrig bockas av på saknad data.
		int current = AccountLevels.totalLevel(data);
		return current < 0 ? null : AccountLevels.progress(current, target);
	}

	@Override
	public String describeProgress(GoalProgress progress)
	{
		return AccountLevels.describe("Total level ", progress, "level", "levels");
	}
}

