/**
 * Kontotyp för den inloggade spelaren, läst från {@code VarbitID.IRONMAN} på klienttråden
 * och läst av UI:t på EDT. Används bara för att sortera ironman-templates först.
 */
@Singleton
public class AccountStatus
{
	private volatile boolean ironman;

	public boolean isIronman()
	{
		return ironman;
	}

	/**
	 * @param ironmanVarbit värdet av VarbitID.IRONMAN; 0 betyder vanligt konto, allt annat
	 *                      någon sorts ironman (vanlig, hardcore, ultimate eller group)
	 */
	public void update(int ironmanVarbit)
	{
		ironman = ironmanVarbit > 0;
	}

	public void reset()
	{
		ironman = false;
	}
}

