		itemPanel = new SearchPanel<>("Type an item name, e.g. dragon pickaxe", services.getItemSearch()::search,
			ItemSearch.ItemOption::getName, item -> itemIcon(item.getId()), 2);
		itemPanel.setHint("Untradeable items are included.");
