	@Test
	public void questCapeWithFullChainsIsFast()
	{
		Gson gson = new Gson();
		TemplateNode cape = new QuestCapeTemplate(QuestCapeExclusions.load(gson)).build(Map.of());
		QuestChains.expand(cape, QuestRequirementsDb.load(gson));
		TemplateInserter.insert(tree, cape, null);
		String rootId = tree.getRoots().get(0).getId();

		// Första körningen värmer upp JIT; den andra mäts.
		layout(MapView.of(rootId));
		long start = System.nanoTime();
		MapLayout layout = layout(MapView.of(rootId));
		long millis = (System.nanoTime() - start) / 1_000_000;

		// Questdatabasen saknar ännu många quests, så kedjorna blir ~220 noder i stället för ~300.
		assertTrue("nodes: " + layout.getNodes().size(), layout.getNodes().size() >= 200);
		assertTrue("took " + millis + " ms", millis < 1000);
		assertNoOverlaps(layout);
		for (MapLayout.Edge edge : layout.getEdges())
		{
			assertTrue(edge.getSpan() >= 1);
		}
	}

	@Test
	public void sixHundredNodesWithSharedSubGoalsAreFast()
	{
		// Deterministisk DAG: 12 lager à 50 noder, varje nod under 1-3 noder i lagret ovanför.
		List<List<Goal>> layers = new ArrayList<>();
		Goal root = add(null, "Root");
		layers.add(List.of(root));
		long seed = 42;
		for (int l = 1; l <= 12; l++)
		{
			List<Goal> layer = new ArrayList<>();
			List<Goal> above = layers.get(l - 1);
			for (int i = 0; i < 50; i++)
			{
				seed = seed * 6364136223846793005L + 1442695040888963407L;
				Goal goal = add(above.get((int) Math.floorMod(seed >>> 33, (long) above.size())), "N" + l + "." + i);
				for (int extra = 0; extra < (int) Math.floorMod(seed >>> 20, 3L); extra++)
				{
					seed = seed * 6364136223846793005L + 1442695040888963407L;
					tree.link(above.get((int) Math.floorMod(seed >>> 33, (long) above.size())).getId(), goal.getId());
				}
				layer.add(goal);
			}
			layers.add(layer);
		}

		layout(MapView.of(root.getId()));
		long start = System.nanoTime();
		MapLayout layout = layout(MapView.of(root.getId()));
		long millis = (System.nanoTime() - start) / 1_000_000;

		assertEquals(601, layout.getNodes().size());
		assertTrue("took " + millis + " ms", millis < 2000);
		assertNoOverlaps(layout);
		assertEquals(coordinates(layout), coordinates(layout(MapView.of(root.getId()))));
	}

	private MapLayout layout(MapView view)
	{
		return LayeredLayout.compute(MapGraph.build(tree, view));
	}

	private Goal add(Goal parent, String title)
	{
		Goal goal = new Goal(title);
		tree.add(parent == null ? null : parent.getId(), goal);
		return goal;
	}

	private static MapLayout.Node node(MapLayout layout, Goal goal)
	{
		MapLayout.Node node = layout.node(goal.getId());
		assertNotNull(goal.getTitle(), node);
		return node;
	}

	private static List<MapLayout.Edge> edgesInto(MapLayout layout, Goal goal)
	{
		List<MapLayout.Edge> edges = new ArrayList<>();
		for (MapLayout.Edge edge : layout.getEdges())
		{
			if (edge.getToId().equals(goal.getId()))
			{
				edges.add(edge);
			}
		}
		return edges;
	}

	private static MapLayout.Edge edge(MapLayout layout, Goal from, Goal to)
	{
		for (MapLayout.Edge edge : layout.getEdges())
		{
			if (edge.getFromId().equals(from.getId()) && edge.getToId().equals(to.getId()))
			{
				return edge;
			}
		}
		throw new AssertionError("No edge " + from.getTitle() + " -> " + to.getTitle());
	}

	private static Map<String, String> coordinates(MapLayout layout)
	{
		Map<String, String> coordinates = new HashMap<>();
		layout.getNodes().forEach(node -> coordinates.put(node.getGoalId(), node.getX() + "," + node.getY()));
		return coordinates;
	}

	private static void assertNoOverlaps(MapLayout layout)
	{
		Map<Integer, List<MapLayout.Node>> byLayer = new HashMap<>();
		layout.getNodes().forEach(node -> byLayer.computeIfAbsent(node.getLayer(), l -> new ArrayList<>()).add(node));
		for (List<MapLayout.Node> layer : byLayer.values())
		{
			layer.sort((a, b) -> Integer.compare(a.getOrder(), b.getOrder()));
			for (int i = 1; i < layer.size(); i++)
			{
				double gap = layer.get(i).getX() - layer.get(i - 1).getX();
				assertTrue("gap " + gap, gap >= LayeredLayout.NODE_WIDTH + LayeredLayout.H_GAP - 1);
			}
		}
	}
}

package com.gielinorgoals.model;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.util.QuantityFormatter;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AccountLevelRequirementsTest
{
	private static final int XP_99 = Experience.getXpForLevel(99);

	@Test
	public void newAccountHasMinimumTotalAndCombatLevel()
	{
		GameData data = levels(1, Map.of(Skill.HITPOINTS, 10));

		assertEquals(AccountLevels.MIN_TOTAL_LEVEL, AccountLevels.totalLevel(data));
		// Alla skills på 1 utom Hitpoints på 10.
		assertEquals(AccountLevels.SKILLS.size() - 1 + 10, AccountLevels.totalLevel(data));
		assertEquals(3, AccountLevels.combatLevel(data));
	}

	@Test
	public void maxedAccountHasMaximumTotalAndCombatLevel()
	{
		GameData data = levels(99, Map.of());

		assertEquals(AccountLevels.MAX_TOTAL_LEVEL, AccountLevels.totalLevel(data));
		assertEquals(AccountLevels.SKILLS.size() * 99, AccountLevels.totalLevel(data));
		assertEquals(126, AccountLevels.combatLevel(data));
	}

	@Test
	public void xpAboveLevel99CountsAsRealLevel99()
	{
		Map<Skill, Long> xp = xpFor(1, Map.of(Skill.HITPOINTS, 10));
		xp.put(Skill.MINING, (long) Experience.MAX_SKILL_XP);
		xp.put(Skill.ATTACK, (long) Experience.getXpForLevel(120));

		GameData data = data(xp);

		// Mining 200M och Attack virtuell 120 räknas båda som 99.
		assertEquals(AccountLevels.MIN_TOTAL_LEVEL + 98 + 98, AccountLevels.totalLevel(data));
	}

	@Test
	public void combatLevelUsesTheGameFormulaWithSkillsInTheRightOrder()
	{
		Map<Skill, Integer> overrides = new EnumMap<>(Skill.class);
		overrides.put(Skill.ATTACK, 60);
		overrides.put(Skill.STRENGTH, 70);
		overrides.put(Skill.DEFENCE, 50);
		overrides.put(Skill.HITPOINTS, 65);
		overrides.put(Skill.MAGIC, 55);
		overrides.put(Skill.RANGED, 60);
		overrides.put(Skill.PRAYER, 43);

		// Bas 0,25 × (50 + 65 + 21) = 34, melee 0,325 × 130 = 42,25, alltså 76.
		assertEquals(76, AccountLevels.combatLevel(levels(1, overrides)));
	}

	@Test
	public void unknownSkillGivesUnknownProgress()
	{
		Map<Skill, Long> xp = xpFor(99, Map.of());
		xp.remove(Skill.SAILING);
		xp.remove(Skill.PRAYER);
		GameData data = data(xp);

		assertNull(new TotalLevelRequirement(1500).progress(data));
		assertNull(new CombatLevelRequirement(100).progress(data));
		assertNull(new QuestPointsRequirement(100).progress(data));
		assertNull(new TotalLevelRequirement(1500).progress(GameData.EMPTY));
	}

	@Test
	public void progressIsCurrentOverTarget()
	{
		GameData data = levels(50, Map.of());
		int total = AccountLevels.SKILLS.size() * 50;

		GoalProgress below = new TotalLevelRequirement(total + 1).progress(data);
		assertEquals(total, below.getCurrent());
		assertEquals(total + 1, below.getTarget());
		assertFalse(below.isComplete());
		assertEquals(QuantityFormatter.formatNumber(total) + "/" + QuantityFormatter.formatNumber(total + 1),
			below.getLabel());

		assertTrue(new TotalLevelRequirement(total).progress(data).isComplete());
	}

	@Test
	public void questPointsComeFromGameData()
	{
		GameData data = questPoints(149);

		GoalProgress progress = new QuestPointsRequirement(150).progress(data);
		assertEquals("149/150", progress.getLabel());
		assertFalse(progress.isComplete());
		assertTrue(new QuestPointsRequirement(149).progress(data).isComplete());
		assertEquals("Quest points 149 / 150\n1 quest point left",
			new QuestPointsRequirement(150).describeProgress(progress));
	}

	@Test
	public void unknownDataNeverChangesCompletion()
	{
		GoalTree tree = new GoalTree();
		Goal open = new Goal("");
		open.setRequirement(new CombatLevelRequirement(3));
		Goal done = new Goal("");
		done.setRequirement(new QuestPointsRequirement(300));
		done.markCompleted(true, 5L);
		tree.add(null, open);
		tree.add(null, done);

		GoalEvaluator.Result result = GoalEvaluator.evaluate(tree, GameData.EMPTY, 1000L);

		assertFalse(open.isCompleted());
		assertTrue(done.isCompleted());
		assertEquals(Long.valueOf(5L), done.getCompletedAt());
		assertTrue(result.getNewlyCompleted().isEmpty());
		assertTrue(result.getProgress().isEmpty());
	}

	@Test
	public void describeGivesReadableTitles()
	{
		assertEquals("Total level 1500", new TotalLevelRequirement(1500).describe());
		assertEquals("Combat level 100", new CombatLevelRequirement(100).describe());
		assertEquals("150 quest points", new QuestPointsRequirement(150).describe());
	}

	@Test
	public void boundsAreEnforced()
	{
		assertThrows(() -> new TotalLevelRequirement(AccountLevels.MIN_TOTAL_LEVEL - 1));
		assertThrows(() -> new TotalLevelRequirement(AccountLevels.MAX_TOTAL_LEVEL + 1));
		assertThrows(() -> new CombatLevelRequirement(2));
		assertThrows(() -> new CombatLevelRequirement(127));
		assertThrows(() -> new QuestPointsRequirement(0));
		assertThrows(() -> new QuestPointsRequirement(QuestPointsRequirement.MAX + 1));
		assertEquals(3, CombatLevelRequirement.MIN);
		assertEquals(126, CombatLevelRequirement.MAX);
	}

	private static void assertThrows(Runnable runnable)
	{
		try
		{
			runnable.run();
		}
		catch (IllegalArgumentException e)
		{
			return;
		}
		throw new AssertionError("Expected IllegalArgumentException");
	}

	// Alla riktiga skills på samma nivå, med valfria undantag.
	private static GameData levels(int level, Map<Skill, Integer> overrides)
	{
		return data(xpFor(level, overrides));
	}

	private static Map<Skill, Long> xpFor(int level, Map<Skill, Integer> overrides)
	{
		Map<Skill, Long> xp = new EnumMap<>(Skill.class);
		for (Skill skill : AccountLevels.SKILLS)
		{
			int skillLevel = overrides.getOrDefault(skill, level);
			xp.put(skill, (long) (skillLevel == 99 ? XP_99 : Experience.getXpForLevel(skillLevel)));
		}
		return xp;
	}

	private static GameData data(Map<Skill, Long> xp)
	{
		return skill -> xp.getOrDefault(skill, -1L);
	}

	private static GameData questPoints(int points)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public int getQuestPoints()
			{
				return points;
			}
		};
	}
}

package com.gielinorgoals.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Map;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

public class AchievementRequirementsTest
{
	@Test
	public void questIsCompleteOnlyWhenFinished()
	{
		QuestRequirement requirement = new QuestRequirement(42, "Dragon Slayer I");

		assertEquals("Not started", requirement.progress(quest(42, QuestState.NOT_STARTED)).getLabel());
		GoalProgress inProgress = requirement.progress(quest(42, QuestState.IN_PROGRESS));
		assertFalse(inProgress.isComplete());
		assertEquals(0.5, inProgress.fraction(), 0.0);
		assertTrue(requirement.progress(quest(42, QuestState.FINISHED)).isComplete());
		assertNull(requirement.progress(GameData.EMPTY));
		assertEquals("Complete Dragon Slayer I", requirement.describe());
	}

	@Test
	public void regularDiaryTierIsCompleteAtOne()
	{
		DiaryRequirement requirement = new DiaryRequirement(DiaryArea.VARROCK, DiaryTier.HARD);
		assertEquals(VarbitID.VARROCK_DIARY_HARD_COMPLETE, requirement.varbit());

		assertFalse(requirement.progress(varbit(requirement.varbit(), 0)).isComplete());
		assertTrue(requirement.progress(varbit(requirement.varbit(), 1)).isComplete());
		assertEquals("Varrock Hard diary", requirement.describe());
	}

	@Test
	public void karamjaLowTiersNeedTwoButEliteNeedsOne()
	{
		DiaryRequirement easy = new DiaryRequirement(DiaryArea.KARAMJA, DiaryTier.EASY);
		assertEquals(VarbitID.ATJUN_EASY_DONE, easy.varbit());
		assertFalse(easy.progress(varbit(easy.varbit(), 1)).isComplete());
		assertTrue(easy.progress(varbit(easy.varbit(), 2)).isComplete());

		DiaryRequirement elite = new DiaryRequirement(DiaryArea.KARAMJA, DiaryTier.ELITE);
		assertEquals(VarbitID.KARAMJA_DIARY_ELITE_COMPLETE, elite.varbit());
		assertTrue(elite.progress(varbit(elite.varbit(), 1)).isComplete());
	}

	@Test
	public void diaryShowsTaskCountWhenKnown()
	{
		DiaryRequirement requirement = new DiaryRequirement(DiaryArea.VARROCK, DiaryTier.EASY);
		GameData data = varbits(Map.of(requirement.varbit(), 0, requirement.countVarbit(), 7));

		GoalProgress progress = requirement.progress(data);

		assertEquals("7/14 tasks", progress.getLabel());
		assertEquals(0.5, progress.fraction(), 0.0);
		assertFalse(progress.isComplete());
	}

	@Test
	public void completedDiaryShowsFullCount()
	{
		DiaryRequirement requirement = new DiaryRequirement(DiaryArea.ARDOUGNE, DiaryTier.ELITE);
		GoalProgress progress = requirement.progress(varbits(Map.of(requirement.varbit(), 1, requirement.countVarbit(), 3)));

		assertTrue(progress.isComplete());
		assertEquals("8/8 tasks", progress.getLabel());
	}

	@Test
	public void journalTitleMapsToArea()
	{
		assertEquals(DiaryArea.VARROCK, DiaryArea.fromJournalTitle("Varrock Area Tasks"));
		assertEquals(DiaryArea.KOUREND, DiaryArea.fromJournalTitle("<col=7f0000>Kourend & Kebos Tasks</col>"));
		assertEquals(DiaryArea.LUMBRIDGE, DiaryArea.fromJournalTitle("Lumbridge & Draynor Tasks"));
		assertNull(DiaryArea.fromJournalTitle("Cook's Assistant"));
	}

	@Test
	public void unreadDiaryVarbitGivesNoProgress()
	{
		assertNull(new DiaryRequirement(DiaryArea.DESERT, DiaryTier.EASY).progress(GameData.EMPTY));
	}

	@Test
	public void combatAchievementFollowsCompletionFlag()
	{
		CombatAchievementRequirement requirement = new CombatAchievementRequirement(17, "Noxious Foe", "Easy");

		assertFalse(requirement.progress(ca(17, false)).isComplete());
		assertTrue(requirement.progress(ca(17, true)).isComplete());
		assertNull(requirement.progress(GameData.EMPTY));
		assertEquals("CA (Easy): Noxious Foe", requirement.describe());
	}

	private static GameData quest(int id, QuestState state)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public QuestState getQuestState(int questId)
			{
				return questId == id ? state : null;
			}
		};
	}

	private static GameData varbit(int id, int value)
	{
		return varbits(Map.of(id, value));
	}

	private static GameData varbits(Map<Integer, Integer> values)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public int getVarbit(int varbitId)
			{
				return values.getOrDefault(varbitId, -1);
			}
		};
	}

	private static GameData ca(int id, boolean complete)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public Boolean isCombatAchievementComplete(int taskId)
			{
				return taskId == id ? complete : null;
			}
		};
	}
}

package com.gielinorgoals.model;

import java.time.LocalDateTime;
