import com.gielinorgoals.model.GoalEvaluator;
import com.gielinorgoals.model.GoalTree;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Regressioner från spel-testet av paketen: "update" direkt efter insättningen, och quests och
 * fairy rings som inte syntes som klara.
 */
public class PackageUpdateTest
{
	private final Gson gson = new Gson();
	private final TemplateCatalog catalog = new TemplateCatalog(gson);
	private final QuestRequirementsDb db = QuestRequirementsDb.load(gson);
	private final TemplateUpdates updates = new TemplateUpdates(catalog, db);

	@Test
	public void freshPackageHasNoUpdateRightAfterInsert()
	{
		for (String id : List.of("package-early-iron", "package-mid-iron", "package-late-iron", "package-all-capes"))
		{
			GoalTree tree = new GoalTree();
			TemplateInserter.insert(tree, asInDialog(tree, id));
			assertEquals(id, List.of(), rootsWithUpdates(tree));
		}
	}

	@Test
	public void packageAfterQuestCapeHasNoUpdate()
	{
		GoalTree tree = new GoalTree();
		// Quest cape som platt lista (utan kedjor), som när man har alla quests som mål sedan tidigare.
		TemplateNode questCape = catalog.find("quest-cape").build(Map.of());
		questCape.setTemplateId("quest-cape");
		questCape.setTemplateParams(Map.of(TemplateUpdates.QUEST_CHAINS_PARAM, 0));
		TemplateInserter.insert(tree, questCape);

		TemplateInserter.insert(tree, asInDialog(tree, "package-early-iron"));
		TemplateInserter.insert(tree, asInDialog(tree, "package-all-capes"));
		assertEquals(List.of(), rootsWithUpdates(tree));
	}

	@Test
	public void anOldPackageGetsTheNewPartsAsAnUpdate()
	{
		// Mid ironman som i version 1, utan delarna från milstolpe 15.
		List<String> added = List.of("barrows-set", "blowpipe-serp", "trident-swamp", "moons-of-peril",
			"dragonfire-shield");
		GoalTree tree = new GoalTree();
		TemplateNode full = asInDialog(tree, "package-mid-iron");
		TemplateNode node = TemplateNode.aggregate(full.getTitle());
		node.setTemplateId(full.getTemplateId());
		node.setTemplateParams(full.getTemplateParams());
		full.getChildren().stream().filter(child -> !added.contains(child.getTemplateId())).forEach(node::add);
		Goal root = TemplateInserter.insert(tree, node).getRoot();
		root.setTemplateVersion(1);

		TemplateUpdates.Plan plan = updates.plan(tree, root);
		assertTrue(plan.isNewVersion());
		List<String> parts = new ArrayList<>();
		plan.getAdditions().forEach(addition ->
		{
			if (addition.getNode().getTemplateId() != null)
			{
				parts.add(addition.getNode().getTemplateId());
			}
		});
		assertTrue(parts.toString(), parts.containsAll(added));
		assertTrue(plan.getRemoved().isEmpty());
	}

	@Test
	public void aRealChangeIsStillFoundAfterTheFix()
	{
		GoalTree tree = new GoalTree();
		Goal root = TemplateInserter.insert(tree, asInDialog(tree, "package-early-iron")).getRoot();
		// Användaren tar bort ett mål som paketet skapade: uppdateringen föreslår det igen.
		Goal scimitar = null;
		for (Goal goal : tree.flatten())
		{
			if ("item:4587".equals(TemplateKeys.of(goal)))
			{
				scimitar = goal;
			}
		}
		tree.remove(scimitar.getId());
		assertTrue(updates.hasUpdate(tree, root, 1));
	}

	@Test
	public void doneWhenIsMetFromTheGameWithoutAGoal()
	{
		// Fairytale II-steget i Ardougne cloak-templaten är klart när questen är klar i spelet.
		TemplateNode node = catalog.find("ardougne-cloak").build(Map.of());
		GoalTree tree = new GoalTree();
		TemplateInserter.insert(tree, node);
		GameData finished = quests(Map.of(Quest.FAIRYTALE_II__CURE_A_QUEEN.getId(), QuestState.FINISHED));
		GoalEvaluator.evaluate(tree, finished, 1L, TemplateKeys::of);
		Goal step = null;
		for (Goal goal : tree.flatten())
		{
			if (goal.getTitle().startsWith("Fairytale II"))
			{
				step = goal;
			}
		}
		assertTrue(step.isCompleted());

		// Och förhandsvisningen visar det som klart.
		TemplatePlanner.Plan plan = TemplatePlanner.plan(new GoalTree(), catalog.find("ardougne-cloak").build(Map.of()),
			finished);
		assertTrue(plan.getAlreadyDone() > 0);
	}

	@Test
	public void doneWhenQuestsAndDiariesAreWatched()
	{
		// Annars läses Fairytale II aldrig, eftersom det inte är ett eget mål.
		GoalTree tree = new GoalTree();
		TemplateInserter.insert(tree, catalog.find("ardougne-cloak").build(Map.of()));
		com.gielinorgoals.tracking.WatchedAchievements watched = com.gielinorgoals.tracking.WatchedAchievements.from(tree);
		assertTrue(watched.getQuestIds().contains(Quest.FAIRYTALE_II__CURE_A_QUEEN.getId()));
		assertTrue(watched.getVarbits().contains(com.gielinorgoals.model.DiaryArea.LUMBRIDGE.varbitFor(
			com.gielinorgoals.model.DiaryTier.ELITE)));
	}

	@Test
	public void previewUsesFullQuestStatus()
	{
		GameData base = quests(Map.of());
		GameData status = quests(Map.of(Quest.COOKS_ASSISTANT.getId(), QuestState.FINISHED));
		CompletionOverlay overlay = new CompletionOverlay(base, status);
		assertEquals(QuestState.FINISHED, overlay.getQuestState(Quest.COOKS_ASSISTANT.getId()));
		assertEquals(null, base.getQuestState(Quest.COOKS_ASSISTANT.getId()));
		assertFalse(overlay.getVarbit(1) >= 0);
	}

	// Som template-dialogen: kedjor påslagna, templateId och kedjeval på roten och delarna.
	private TemplateNode asInDialog(GoalTree tree, String id)
	{
		TemplateNode node = catalog.find(id).build(Map.of());
		QuestChains.expand(node, db, tree);
		node.setTemplateId(id);
		node.setTemplateParams(Map.of(TemplateUpdates.QUEST_CHAINS_PARAM, 1));
		markChains(node);
		return node;
	}

	private static void markChains(TemplateNode node)
	{
		for (TemplateNode child : node.getChildren())
		{
			if (child.getTemplateId() != null && child.getTemplateParams() != null)
			{
				Map<String, Integer> params = new HashMap<>(child.getTemplateParams());
				params.put(TemplateUpdates.QUEST_CHAINS_PARAM, 1);
				child.setTemplateParams(params);
			}
			markChains(child);
		}
	}

	private List<String> rootsWithUpdates(GoalTree tree)
	{
		List<String> out = new ArrayList<>();
		for (Goal goal : tree.flatten())
		{
			if (goal.getTemplateId() != null && !"quest-cape".equals(goal.getTemplateId()))
			{
				TemplateUpdates.Plan plan = updates.plan(tree, goal);
				if (plan != null && !plan.isEmpty())
				{
					List<String> keys = new ArrayList<>();
					plan.getAdditions().forEach(addition -> keys.add("+" + addition.getNode().getKey()));
					plan.getRemoved().forEach(removed -> keys.add("-" + TemplateKeys.of(removed)));
					out.add(goal.getTemplateId() + " " + keys.subList(0, Math.min(5, keys.size())));
				}
			}
		}
		return out;
	}

	private static GameData quests(Map<Integer, QuestState> states)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public QuestState getQuestState(int questId)
			{
				return states.get(questId);
			}
		};
	}
}

package com.gielinorgoals.template;

import com.gielinorgoals.model.GameData;
import com.gielinorgoals.model.Goal;
import com.gielinorgoals.model.GoalTree;
import com.gielinorgoals.model.QuestPointsRequirement;
import com.gielinorgoals.model.QuestRequirement;
import com.gielinorgoals.model.Requirement;
import com.gielinorgoals.model.SkillRequirement;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class QuestChainsTest
{
	private final QuestRequirementsDb db = QuestRequirementsDb.load(new Gson());

	@Test
	public void eachQuestIsExpandedOnceAndLaterCopiesAreLeaves()
	{
		TemplateNode rfd = QuestChains.forQuest("", quest(Quest.RECIPE_FOR_DISASTER), false, db, null);

		Map<Integer, Integer> withChildren = new HashMap<>();
		for (TemplateNode node : all(rfd))
		{
			if (node.getRequirement() instanceof QuestRequirement && !node.getChildren().isEmpty())
			{
				withChildren.merge(((QuestRequirement) node.getRequirement()).getQuestId(), 1, Integer::sum);
			}
		}
		for (Map.Entry<Integer, Integer> entry : withChildren.entrySet())
		{
			assertEquals("quest " + entry.getKey(), Integer.valueOf(1), entry.getValue());
		}
		// Priest in Peril finns i flera grenar (Nature Spirit, Desert Treasure I).
		assertTrue(count(rfd, quest(Quest.PRIEST_IN_PERIL)) > 1);
	}

	@Test
	public void onlyTheHighestSkillAndQuestPointRequirementsBecomeGoals()
	{
		TemplateNode rfd = QuestChains.forQuest("", quest(Quest.RECIPE_FOR_DISASTER), false, db, null);

		Set<Integer> cookingLevels = new HashSet<>();
		Set<Integer> agilityLevels = new HashSet<>();
		Set<Integer> questPoints = new HashSet<>();
		for (TemplateNode node : all(rfd))
		{
			Requirement requirement = node.getRequirement();
			if (requirement instanceof SkillRequirement && ((SkillRequirement) requirement).getSkill() == Skill.COOKING)
			{
				cookingLevels.add((int) ((SkillRequirement) requirement).getTarget());
				// Cooking 70 går att boosta enligt wikin.
				assertEquals("70 Cooking (boostable)", node.getDisplayTitle());
			}
			if (requirement instanceof SkillRequirement && ((SkillRequirement) requirement).getSkill() == Skill.AGILITY)
			{
				agilityLevels.add((int) ((SkillRequirement) requirement).getTarget());
				// Agility 48 går inte att boosta.
				assertEquals("48 Agility", node.getDisplayTitle());
			}
			if (requirement instanceof QuestPointsRequirement)
			{
				questPoints.add(((QuestPointsRequirement) requirement).getTarget());
			}
		}
		assertEquals(Set.of(70), cookingLevels);
		assertEquals(Set.of(48), agilityLevels);
		assertEquals(Set.of(175), questPoints);
	}

	@Test
	public void partialRequirementBecomesOneManualStep()
	{
		TemplateNode rfd = QuestChains.forQuest("", quest(Quest.RECIPE_FOR_DISASTER), false, db, null);

		List<String> partial = new ArrayList<>();
		for (TemplateNode node : all(rfd))
		{
			if (node.getRequirement() == null && node.getTitle().endsWith("(partial requirement)"))
			{
				partial.add(node.getTitle());
			}
		}
		assertEquals(1, partial.size());
		assertTrue(partial.get(0).contains("Legends' Quest"));
	}

	@Test
	public void insertedChainHasNoDuplicatesAndSharesQuests()
	{
		GoalTree tree = new GoalTree();
		Goal existingPriest = new Goal("");
		existingPriest.setRequirement(quest(Quest.PRIEST_IN_PERIL));
		Goal existingAgility = new Goal("");
		existingAgility.setRequirement(SkillRequirement.level(Skill.AGILITY, 48));
		Goal nearAgility = new Goal("");
		nearAgility.setRequirement(SkillRequirement.level(Skill.AGILITY, 50));
		tree.add(null, existingPriest);
		tree.add(null, existingAgility);
		tree.add(null, nearAgility);

		TemplateNode gloves = HandpickedTemplatesTest.barrowsGloves().build(Map.of());
		QuestChains.expand(gloves, db, tree);
		TemplatePlanner.Plan plan = TemplatePlanner.plan(tree, gloves, GameData.EMPTY);
		TemplateInserter.Result result = TemplateInserter.insert(tree, gloves);

		// Varje krav finns som ett enda mål.
		List<String> seen = new ArrayList<>();
		for (Goal goal : tree.flatten())
		{
			if (goal.getRequirement() != null)
			{
				for (String other : seen)
				{
					assertFalse("Duplicate " + goal.getDisplayTitle(), other.equals(key(goal.getRequirement())));
				}
				seen.add(key(goal.getRequirement()));
			}
		}
		// Befintliga exakta mål kopplas in; Agility 50 är inte samma som 48.
		assertTrue(result.getLinked().contains(existingPriest));
		assertTrue(result.getLinked().contains(existingAgility));
		assertFalse(result.getLinked().contains(nearAgility));
		assertTrue(tree.getParents(existingPriest.getId()).size() > 1);
		assertEquals(result.getCreated().size() - 1, plan.getNewGoals());
	}

	@Test
	public void questWithoutDataStaysAPlainQuestGoal()
	{
		Quest missing = null;
		for (Quest quest : Quest.values())
		{
			if (db.get(quest.getId()) == null)
			{
				missing = quest;
				break;
			}
		}
		TemplateNode node = QuestChains.forQuest("", quest(missing), false, db, null);

		assertTrue(node.getChildren().isEmpty());
	}

	@Test
	public void questCapeIsFlatByDefaultAndHandpickedTemplatesExpand()
	{
		assertFalse(new QuestCapeTemplate(QuestCapeExclusions.load(new Gson())).defaultExpandQuestChains());
		assertTrue(HandpickedTemplatesTest.barrowsGloves().defaultExpandQuestChains());
		assertFalse(QuestChains.hasQuestNodes(new BaseLevelTemplate().build(Map.of())));
	}

	private static QuestRequirement quest(Quest quest)
	{
		return new QuestRequirement(quest.getId(), quest.getName());
	}

	private static String key(Requirement requirement)
	{
		if (requirement instanceof QuestRequirement)
		{
			return "quest:" + ((QuestRequirement) requirement).getQuestId();
		}
		return requirement.getType() + ":" + requirement.describe();
	}

	private static int count(TemplateNode root, Requirement requirement)
	{
		int count = 0;
		for (TemplateNode node : all(root))
		{
			if (requirement.isSameGoal(node.getRequirement()))
			{
				count++;
			}
		}
		return count;
	}

	private static List<TemplateNode> all(TemplateNode root)
	{
		List<TemplateNode> nodes = new ArrayList<>();
		collect(root, nodes);
		return nodes;
	}

	private static void collect(TemplateNode node, List<TemplateNode> out)
	{
		out.add(node);
		for (TemplateNode child : node.getChildren())
		{
			collect(child, out);
		}
	}
}

package com.gielinorgoals.template;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Test;

public class QuestRequirementsDbTest
{
	private final QuestRequirementsDb db = QuestRequirementsDb.load(new Gson());
	private final Map<Integer, String> enumNames = new HashMap<>();

	{
		for (Quest quest : Quest.values())
		{
			enumNames.put(quest.getId(), quest.getName());
		}
	}

	@Test
	public void priorityChainsAreLoaded()
	{
		for (Quest quest : new Quest[]{Quest.SONG_OF_THE_ELVES, Quest.RECIPE_FOR_DISASTER, Quest.DRAGON_SLAYER_II,
			Quest.DESERT_TREASURE_I, Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE, Quest.MONKEY_MADNESS_II})
		{
			assertNotNull(quest.getName(), db.get(quest.getId()));
		}
		assertEquals(Integer.valueOf(175), db.get(Quest.RECIPE_FOR_DISASTER.getId()).getQuestPoints());
	}

	@Test
	public void everyReferencePointsAtAnExistingQuestWithTheSameName()
	{
		for (QuestRequirementsDb.Entry entry : db.all().values())
		{
			assertEquals("entry " + entry.getId(), enumNames.get(entry.getId()), entry.getName());
			for (QuestRequirementsDb.Ref ref : entry.getQuests())
			{
				assertEquals(entry.getName() + " -> " + ref.getName(), enumNames.get(ref.getId()), ref.getName());
			}
			for (QuestRequirementsDb.Partial partial : entry.getPartial())
			{
				assertEquals(entry.getName() + " partial", enumNames.get(partial.getId()), partial.getName());
				assertTrue(partial.getText() != null && !partial.getText().isEmpty());
			}
		}
	}

	@Test
	public void everyPrerequisiteHasItsOwnEntry()
	{
		// Kedjorna ska kunna fällas ut hela vägen för de quests som finns i filen.
		List<String> missing = new ArrayList<>();
		for (QuestRequirementsDb.Entry entry : db.all().values())
		{
			for (QuestRequirementsDb.Ref ref : entry.getQuests())
			{
				if (db.get(ref.getId()) == null)
				{
					missing.add(entry.getName() + " -> " + ref.getName());
				}
			}
		}
		assertTrue("Prerequisites without an entry: " + missing, missing.isEmpty());
	}

	@Test
	public void skillNamesAndLevelsAreValid()
	{
		for (QuestRequirementsDb.Entry entry : db.all().values())
		{
			for (QuestRequirementsDb.SkillReq req : entry.getSkills())
			{
				try
				{
					Skill.valueOf(req.getSkill());
				}
				catch (IllegalArgumentException e)
				{
					fail(entry.getName() + " has unknown skill " + req.getSkill());
				}
				assertTrue(entry.getName() + " " + req.getSkill(), req.getLevel() >= 2 && req.getLevel() <= 99);
			}
		}
	}

	@Test
	public void thereAreNoCycles()
	{
		Set<Integer> done = new HashSet<>();
		for (int id : db.all().keySet())
		{
			visit(id, new HashSet<>(), done);
		}
	}

	private void visit(int id, Set<Integer> path, Set<Integer> done)
	{
		if (done.contains(id))
		{
			return;
		}
		if (!path.add(id))
		{
			fail("Cycle through " + enumNames.get(id));
		}
		QuestRequirementsDb.Entry entry = db.get(id);
		if (entry != null)
		{
			for (QuestRequirementsDb.Ref ref : entry.getQuests())
			{
				visit(ref.getId(), path, done);
			}
		}
		path.remove(id);
		done.add(id);
	}

	@Test
	public void questsMissingFromTheFileAreListedButDoNotFail()
	{
		List<String> missing = db.missingQuests();
		System.out.println("Quests without requirement data (" + missing.size() + " of " + Quest.values().length + "): "
			+ missing);
		assertNull(db.get(-12345));
	}
}

